-- ============================================================================
-- Lexical Analyzer for Lua 5.4 Syntax
-- File: lexer.lua
-- Language: Lua (Output/Comments in English)
-- ============================================================================

local Lexer = {}
Lexer.__index = Lexer

-- Token Types definition
Lexer.TokenTypes = {
    KEYWORD = "KEYWORD",
    IDENTIFIER = "IDENTIFIER",
    NUMBER = "NUMBER",
    STRING = "STRING",
    OPERATOR = "OPERATOR",
    COMMENT = "COMMENT",
    EOF = "EOF",
}

-- Reserved Keywords in Lua
local KEYWORDS = {
    ["and"] = true,
    ["break"] = true,
    ["do"] = true,
    ["else"] = true,
    ["elseif"] = true,
    ["end"] = true,
    ["false"] = true,
    ["for"] = true,
    ["function"] = true,
    ["goto"] = true,
    ["if"] = true,
    ["in"] = true,
    ["local"] = true,
    ["nil"] = true,
    ["not"] = true,
    ["or"] = true,
    ["repeat"] = true,
    ["return"] = true,
    ["then"] = true,
    ["true"] = true,
    ["until"] = true,
    ["while"] = true,
}

-- Multi-character operators sorted by length (descending) to avoid partial matches
local MULTI_OPS = {
    "...",
    "..",
    "==",
    "~=",
    "<=",
    ">=",
    "//",
    "::",
    "<<",
    ">>",
}

-- Single-character operators/symbols
local SINGLE_OPS = {
    "+",
    "-",
    "*",
    "/",
    "%",
    "^",
    "#",
    "&",
    "~",
    "|",
    "<",
    ">",
    "=",
    "(",
    ")",
    "{",
    "}",
    "[",
    "]",
    ";",
    ":",
    ",",
    ".",
}

--- Instantiates a new Lexer
-- @param input String containing the source code to tokenize
function Lexer.new(input)
    local self = setmetatable({}, Lexer)
    self.input = input
    self.pos = 1
    self.length = #input
    self.line = 1
    self.column = 1
    return self
end

-- Helper: Peek current character
function Lexer:peek(offset)
    offset = offset or 0
    local target = self.pos + offset
    if target > self.length then
        return nil
    end
    return self.input:sub(target, target)
end

-- Helper: Advance character position
function Lexer:advance(count)
    count = count or 1
    for i = 1, count do
        if self:peek() == "\n" then
            self.line = self.line + 1
            self.column = 1
        else
            self.column = self.column + 1
        end
        self.pos = self.pos + 1
    end
end

-- Skip Whitespace
function Lexer:skipWhitespace()
    while self.pos <= self.length do
        local ch = self:peek()
        if ch == " " or ch == "\t" or ch == "\r" or ch == "\n" then
            self:advance()
        else
            break
        end
    end
end

-- Check matching bracket level for long strings and long comments (e.g., `[=...=[`)
function Lexer:readLongBracketLevel()
    local level = 0
    self:advance() -- skip initial '['
    while self:peek() == "=" do
        level = level + 1
        self:advance()
    end
    if self:peek() == "[" then
        self:advance() -- skip closing '['
        return level
    end
    return nil
end

-- Lex Long String or Long Comment content given the opening bracket level
function Lexer:readLongString(level)
    local start_pos = self.pos
    while self.pos <= self.length do
        if self:peek() == "]" then
            self:advance()
            local current_level = 0
            while self:peek() == "=" do
                current_level = current_level + 1
                self:advance()
            end
            if current_level == level and self:peek() == "]" then
                self:advance()
                -- Extract inner contents excluding opening and closing delimiters
                return self.input:sub(start_pos, self.pos - level - 3)
            end
        else
            self:advance()
        end
    end
    error(string.format("Lexer Error: Unclosed long string/comment near line %d", self.line))
end

-- Read standard single or double-quoted string
function Lexer:readString(quote)
    self:advance() -- skip opening quote
    local start_pos = self.pos
    local escaped = false

    while self.pos <= self.length do
        local ch = self:peek()
        if escaped then
            escaped = false
            self:advance()
        elseif ch == "\\" then
            escaped = true
            self:advance()
        elseif ch == quote then
            local val = self.input:sub(start_pos, self.pos - 1)
            self:advance() -- skip closing quote
            return val
        elseif ch == "\n" then
            error(string.format("Lexer Error: Unescaped newline in string at line %d", self.line))
        else
            self:advance()
        end
    end
    error(string.format("Lexer Error: Unclosed string literal near line %d", self.line))
end

-- Read numeric literals (Integers, Floats, Hexadecimal, Scientific notation)
function Lexer:readNumber()
    local start_pos = self.pos

    -- Hexadecimal numbers
    if self:peek() == "0" and (self:peek(1) == "x" or self:peek(1) == "X") then
        self:advance(2)
        while self.pos <= self.length do
            local ch = self:peek()
            if ch:find("[0-9a-fA-F.]") or ch == "p" or ch == "P" or ch == "+" or ch == "-" then
                self:advance()
            else
                break
            end
        end
        return self.input:sub(start_pos, self.pos - 1)
    end

    -- Decimal numbers (integer/float/exponent)
    while self.pos <= self.length do
        local ch = self:peek()
        if ch and (ch:find("[%d%.]") or ch == "e" or ch == "E") then
            self:advance()
            -- Handle exponent signs (e.g. 1e+10 or 1e-5)
            if (self:peek(-1) == "e" or self:peek(-1) == "E") and (self:peek() == "+" or self:peek() == "-") then
                self:advance()
            end
        else
            break
        end
    end

    return self.input:sub(start_pos, self.pos - 1)
end

-- Read Identifiers or Keywords
function Lexer:readIdentifier()
    local start_pos = self.pos
    while self.pos <= self.length do
        local ch = self:peek()
        if ch and ch:find("[%w_]") then
            self:advance()
        else
            break
        end
    end
    return self.input:sub(start_pos, self.pos - 1)
end

--- Retrieves the next token from the input stream
-- @return table Token table containing type, value, line, and column
function Lexer:nextToken()
    self:skipWhitespace()

    if self.pos > self.length then
        return { type = Lexer.TokenTypes.EOF, value = "EOF", line = self.line, column = self.column }
    end

    local start_line = self.line
    local start_col = self.column
    local ch = self:peek()

    -- 1. Comments & Long Comments
    if ch == "-" and self:peek(1) == "-" then
        self:advance(2)
        if self:peek() == "[" then
            local saved_pos = self.pos
            local level = self:readLongBracketLevel()
            if level then
                local comment_text = self:readLongString(level)
                return { type = Lexer.TokenTypes.COMMENT, value = comment_text, line = start_line, column = start_col }
            else
                self.pos = saved_pos -- Rollback if not a long comment delimiter
            end
        end

        -- Short comment (reads until end of line)
        local start_pos = self.pos
        while self.pos <= self.length and self:peek() ~= "\n" do
            self:advance()
        end
        local comment_text = self.input:sub(start_pos, self.pos - 1)
        return { type = Lexer.TokenTypes.COMMENT, value = comment_text, line = start_line, column = start_col }
    end

    -- 2. Strings (Short & Long)
    if ch == '"' or ch == "'" then
        local str = self:readString(ch)
        return { type = Lexer.TokenTypes.STRING, value = str, line = start_line, column = start_col }
    elseif ch == "[" then
        local saved_pos = self.pos
        local saved_col = self.column
        local saved_line = self.line
        local level = self:readLongBracketLevel()
        if level then
            local str = self:readLongString(level)
            return { type = Lexer.TokenTypes.STRING, value = str, line = start_line, column = start_col }
        end
        -- Reset if it's just a regular square bracket operator `[`
        self.pos = saved_pos
        self.column = saved_col
        self.line = saved_line
    end

    -- 3. Numbers (including numbers starting with `.`, e.g., `.5`)
    if ch:find("%d") or (ch == "." and self:peek(1) and self:peek(1):find("%d")) then
        local num = self:readNumber()
        return { type = Lexer.TokenTypes.NUMBER, value = num, line = start_line, column = start_col }
    end

    -- 4. Identifiers & Keywords
    if ch:find("[%a_]") then
        local id = self:readIdentifier()
        local token_type = KEYWORDS[id] and Lexer.TokenTypes.KEYWORD or Lexer.TokenTypes.IDENTIFIER
        return { type = token_type, value = id, line = start_line, column = start_col }
    end

    -- 5. Multi-character Operators
    for _, op in ipairs(MULTI_OPS) do
        local match = true
        for i = 1, #op do
            if self:peek(i - 1) ~= op:sub(i, i) then
                match = false
                break
            end
        end
        if match then
            self:advance(#op)
            return { type = Lexer.TokenTypes.OPERATOR, value = op, line = start_line, column = start_col }
        end
    end

    -- 6. Single-character Operators
    for _, op in ipairs(SINGLE_OPS) do
        if ch == op then
            self:advance(1)
            return { type = Lexer.TokenTypes.OPERATOR, value = op, line = start_line, column = start_col }
        end
    end

    error(string.format("Lexer Error: Unexpected character '%s' at line %d, column %d", ch, self.line, self.column))
end

--- Utility function to tokenize an entire script string into a table
function Lexer:tokenize()
    local tokens = {}
    while true do
        local token = self:nextToken()
        table.insert(tokens, token)
        if token.type == Lexer.TokenTypes.EOF then
            break
        end
    end
    return tokens
end

return Lexer

end

package.preload["parser"] = function(...)
-- Recursive-descent parser for the Lua subset supported by Luash.

local Parser = {}
Parser.__index = Parser

function Parser.new(tokens)
    return setmetatable({ tokens = tokens, pos = 1 }, Parser)
end

function Parser:peek(offset)
    offset = offset or 0
    return self.tokens[self.pos + offset]
end

function Parser:advance()
    local token = self:peek()
    if token and token.type ~= "EOF" then
        self.pos = self.pos + 1
    end
    return token
end

function Parser:expect(tokenType, value)
    local token = self:peek()
    if not token or token.type ~= tokenType or (value and token.value ~= value) then
        error(
            string.format(
                "Parse Error: expected %s %s, got %s '%s' at line %d",
                tokenType,
                value or "",
                token and token.type or "EOF",
                token and token.value or "",
                token and token.line or -1
            )
        )
    end
    return self:advance()
end

function Parser:getOperatorPrecedence(operator)
    local precedences = {
        ["or"] = 1,
        ["and"] = 2,
        ["=="] = 3,
        ["~="] = 3,
        ["<"] = 3,
        [">"] = 3,
        ["<="] = 3,
        [">="] = 3,
        [".."] = 4,
        ["+"] = 5,
        ["-"] = 5,
        ["*"] = 6,
        ["/"] = 6,
        ["%"] = 6,
        ["^"] = 8,
    }
    return precedences[operator]
end

function Parser:parseExpression(minPrecedence)
    minPrecedence = minPrecedence or 0
    local left = self:parsePrimary()

    while true do
        local token = self:peek()
        local isWordOperator = token and token.type == "KEYWORD" and (token.value == "and" or token.value == "or")
        local isSymbolOperator = token and token.type == "OPERATOR"
        if not isWordOperator and not isSymbolOperator then
            break
        end

        local precedence = self:getOperatorPrecedence(token.value)
        if not precedence or precedence < minPrecedence then
            break
        end

        local operator = self:advance().value
        local rightAssociative = operator == "^" or operator == ".."
        local right = self:parseExpression(precedence + (rightAssociative and 0 or 1))
        left = { type = "BinaryExpr", operator = operator, left = left, right = right }
    end

    return left
end

function Parser:parseCall(callee)
    self:expect("OPERATOR", "(")
    local arguments = {}
    if self:peek().value ~= ")" then
        repeat
            table.insert(arguments, self:parseExpression())
            if self:peek().value ~= "," then
                break
            end
            self:advance()
        until false
    end
    self:expect("OPERATOR", ")")
    return { type = "CallExpr", callee = callee, args = arguments }
end

function Parser:parsePrimary()
    local token = self:peek()
    if not token then
        error("Parse Error: unexpected end of input in expression")
    end

    if token.type == "NUMBER" then
        return { type = "Literal", value = tonumber(self:advance().value) }
    elseif token.type == "STRING" then
        return { type = "Literal", value = self:advance().value }
    elseif token.type == "KEYWORD" and (token.value == "true" or token.value == "false") then
        return { type = "Literal", value = self:advance().value == "true" }
    elseif token.type == "KEYWORD" and token.value == "nil" then
        self:advance()
        return { type = "Literal", value = nil }
    elseif token.type == "IDENTIFIER" then
        local name = self:advance().value
        while self:peek() and self:peek().value == "." do
            self:advance()
            name = name .. "." .. self:expect("IDENTIFIER").value
        end
        if self:peek() and self:peek().value == "(" then
            return self:parseCall(name)
        end
        return { type = "Identifier", name = name }
    elseif token.type == "OPERATOR" and token.value == "(" then
        self:advance()
        local expression = self:parseExpression()
        self:expect("OPERATOR", ")")
        return expression
    elseif token.type == "OPERATOR" and (token.value == "-" or token.value == "#") then
        local operator = self:advance().value
        return { type = "UnaryExpr", operator = operator, operand = self:parseExpression(7) }
    elseif token.type == "KEYWORD" and token.value == "not" then
        self:advance()
        return { type = "UnaryExpr", operator = "not", operand = self:parseExpression(7) }
    end

    error(string.format("Parse Error: unexpected token in expression: %s '%s'", token.type, token.value))
end

function Parser:parseNameList(firstName)
    local names = { firstName }
    while self:peek() and self:peek().value == "," do
        self:advance()
        table.insert(names, self:expect("IDENTIFIER").value)
    end
    return names
end

function Parser:parseIfStatement()
    self:expect("KEYWORD", "if")
    local condition = self:parseExpression()
    self:expect("KEYWORD", "then")
    local statement = {
        type = "IfStmt",
        condition = condition,
        body = self:parseBlock({ "else", "elseif", "end" }),
    }

    statement.elseifs = {}
    while self:peek().type == "KEYWORD" and self:peek().value == "elseif" do
        self:advance()
        local elseifCondition = self:parseExpression()
        self:expect("KEYWORD", "then")
        table.insert(statement.elseifs, {
            condition = elseifCondition,
            body = self:parseBlock({ "else", "elseif", "end" }),
        })
    end
    if #statement.elseifs == 0 then
        statement.elseifs = nil
    end

    if self:peek().type == "KEYWORD" and self:peek().value == "else" then
        self:advance()
        statement.elseBody = self:parseBlock({ "end" })
    end
    self:expect("KEYWORD", "end")
    return statement
end

function Parser:parseFunctionDecl(isLocal)
    self:expect("KEYWORD", "function")
    local name = self:expect("IDENTIFIER").value
    self:expect("OPERATOR", "(")
    local params = {}
    if self:peek().value ~= ")" then
        repeat
            table.insert(params, self:expect("IDENTIFIER").value)
            if self:peek().value ~= "," then
                break
            end
            self:advance()
        until false
    end
    self:expect("OPERATOR", ")")
    local body = self:parseBlock({ "end" })
    self:expect("KEYWORD", "end")
    return { type = "FunctionDecl", name = name, params = params, body = body, isLocal = isLocal }
end

function Parser:parseStatement()
    local token = self:peek()
    if token.type == "COMMENT" or (token.type == "OPERATOR" and token.value == ";") then
        self:advance()
        return { type = "NoOp" }
    end

    if token.type == "KEYWORD" and token.value == "local" then
        self:advance()
        if self:peek().type == "KEYWORD" and self:peek().value == "function" then
            return self:parseFunctionDecl(true)
        end
        local names = self:parseNameList(self:expect("IDENTIFIER").value)
        self:expect("OPERATOR", "=")
        local init = self:parseExpression()
        if #names == 1 then
            return { type = "LocalVarDecl", name = names[1], init = init }
        end
        return { type = "MultiLocalVarDecl", names = names, init = init }
    elseif token.type == "KEYWORD" and token.value == "function" then
        return self:parseFunctionDecl(false)
    elseif token.type == "KEYWORD" and token.value == "if" then
        return self:parseIfStatement()
    elseif token.type == "KEYWORD" and token.value == "return" then
        self:advance()
        return { type = "ReturnStmt", value = self:parseExpression() }
    elseif token.type == "IDENTIFIER" then
        local nextToken = self:peek(1)
        if nextToken and (nextToken.value == "=" or nextToken.value == ",") then
            local names = self:parseNameList(self:advance().value)
            self:expect("OPERATOR", "=")
            local init = self:parseExpression()
            if #names == 1 then
                return { type = "AssignmentStmt", name = names[1], init = init }
            end
            return { type = "MultiAssignmentStmt", names = names, init = init }
        end
        return { type = "ExprStmt", expr = self:parseExpression() }
    end

    error(string.format("Parse Error: unknown statement token %s '%s' at line %d", token.type, token.value, token.line))
end

function Parser:parseBlock(terminators)
    local statements = {}
    local terminatorMap = {}
    for _, terminator in ipairs(terminators) do
        terminatorMap[terminator] = true
    end

    while self:peek() and self:peek().type ~= "EOF" do
        local token = self:peek()
        if token.type == "KEYWORD" and terminatorMap[token.value] then
            break
        end
        local statement = self:parseStatement()
        if statement.type ~= "NoOp" then
            table.insert(statements, statement)
        end
    end
    return statements
end

function Parser:parse()
    return { type = "Program", body = self:parseBlock({}) }
end

return Parser

end

